#!/usr/bin/env node
// Generates the iOS shell's image assets so the Mac never has to:
//   1. (the launch icon is generated by app/scripts/gen-splash-assets.py — see below)
//   2. the complete AppIcon asset catalog, rendered from the SAME SVG as the PWA icon
//
// PART 3.7 asks the launch screen to pixel-match the web app's first paint. The app's arrival is
// the wordmark on #0B0B0F, so the storyboard is that ground colour with this wordmark centred —
// the handoff from native launch to web first-paint is then just the wordmark's own fade.
//
// Rendered through Playwright/Chromium, exactly like scripts/gen-icon.mjs, so there is one
// rendering path in the repo and no new dependency.
import { chromium } from 'playwright';
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SHELL = join(ROOT, 'ship/ios/pwa-shell/Assets.xcassets');

const browser = await chromium.launch();

// ── 1. launch icon ─────────────────────────────────────────────────────────────────────────
// The launch screen is the app's frame zero: the unlit, closed scroll on the ground colour. It is
// produced by the SAME pipeline as the web splash's layers (app/scripts/gen-splash-assets.py →
// LaunchIcon.imageset launch-icon@{1,2,3}x.png), so the storyboard and the first web paint are one
// image. Nothing to render here.
console.log('  launch icon: from app/scripts/gen-splash-assets.py (LaunchIcon.imageset)');

// ── 2. app icon ────────────────────────────────────────────────────────────────────────────
// The same gold scroll mark as the PWA icon and the 1024 already in /store. Rendered opaque: the
// App Store 1024 must have NO alpha channel or the upload is rejected outright, and iOS icons are
// always composited on an opaque square anyway.
function iconSvg(size) {
  const s = 512;
  const g = '#C9A24B';
  const hi = '#E3C87A';
  const dark = '#0B0B0F';
  return `<!doctype html><meta charset="utf-8"><style>*{margin:0}html,body{background:${dark}}</style>
<svg width="${size}" height="${size}" viewBox="0 0 ${s} ${s}" xmlns="http://www.w3.org/2000/svg">
  <rect width="${s}" height="${s}" fill="${dark}"/>
  <radialGradient id="aura" cx="50%" cy="42%" r="60%">
    <stop offset="0%" stop-color="${g}" stop-opacity="0.16"/>
    <stop offset="100%" stop-color="${g}" stop-opacity="0"/>
  </radialGradient>
  <rect width="${s}" height="${s}" fill="url(#aura)"/>
  <linearGradient id="gold" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${hi}"/>
    <stop offset="55%" stop-color="${g}"/>
    <stop offset="100%" stop-color="#a8853c"/>
  </linearGradient>
  <path d="M150 150 Q256 120 362 150 L362 362 Q256 392 150 362 Z" fill="#E8DCC0"/>
  <path d="M150 150 Q256 120 362 150 L362 362 Q256 392 150 362 Z" fill="none" stroke="rgba(120,95,45,.25)" stroke-width="3"/>
  <rect x="126" y="118" width="26" height="276" rx="13" fill="url(#gold)"/>
  <rect x="360" y="118" width="26" height="276" rx="13" fill="url(#gold)"/>
  <circle cx="139" cy="118" r="15" fill="url(#gold)"/>
  <circle cx="139" cy="394" r="15" fill="url(#gold)"/>
  <circle cx="373" cy="118" r="15" fill="url(#gold)"/>
  <circle cx="373" cy="394" r="15" fill="url(#gold)"/>
  <g stroke="rgba(90,72,38,.35)" stroke-width="6" stroke-linecap="round">
    <line x1="186" y1="196" x2="326" y2="188"/>
    <line x1="186" y1="232" x2="326" y2="226"/>
    <line x1="186" y1="268" x2="300" y2="264"/>
    <line x1="186" y1="304" x2="326" y2="300"/>
  </g>
</svg>`;
}

async function icon(px) {
  const page = await browser.newPage({ viewport: { width: px, height: px }, deviceScaleFactor: 1 });
  await page.setContent(iconSvg(px));
  await page.waitForTimeout(120);
  const buf = await page.screenshot({ omitBackground: false }); // opaque: no alpha channel
  await page.close();
  return buf;
}

// every size an iPhone-only iOS app needs, plus the 1024 marketing icon
const ICONS = [
  [40, '20@2x.png'], [60, '20@3x.png'],
  [58, '29@2x.png'], [87, '29@3x.png'],
  [80, '40@2x.png'], [120, '40@3x.png'],
  [120, '60@2x.png'], [180, '60@3x.png'],
  [1024, '1024.png'],
];
const iconDir = join(SHELL, 'AppIcon.appiconset');
mkdirSync(iconDir, { recursive: true });
for (const [px, name] of ICONS) writeFileSync(join(iconDir, name), await icon(px));
writeFileSync(
  join(iconDir, 'Contents.json'),
  JSON.stringify(
    {
      images: [
        { size: '20x20', idiom: 'iphone', filename: '20@2x.png', scale: '2x' },
        { size: '20x20', idiom: 'iphone', filename: '20@3x.png', scale: '3x' },
        { size: '29x29', idiom: 'iphone', filename: '29@2x.png', scale: '2x' },
        { size: '29x29', idiom: 'iphone', filename: '29@3x.png', scale: '3x' },
        { size: '40x40', idiom: 'iphone', filename: '40@2x.png', scale: '2x' },
        { size: '40x40', idiom: 'iphone', filename: '40@3x.png', scale: '3x' },
        { size: '60x60', idiom: 'iphone', filename: '60@2x.png', scale: '2x' },
        { size: '60x60', idiom: 'iphone', filename: '60@3x.png', scale: '3x' },
        { size: '1024x1024', idiom: 'ios-marketing', filename: '1024.png', scale: '1x' },
      ],
      info: { author: 'xcode', version: 1 },
    },
    null,
    2,
  ),
);
console.log(`  app icon: ${ICONS.length} sizes -> AppIcon.appiconset`);

// the App Store listing's copy of the same 1024
writeFileSync(join(ROOT, 'store/appicon-1024.png'), await icon(1024));
console.log('  store/appicon-1024.png refreshed');

await browser.close();
